276	// resolveAgentAndTranscript resolves the agent and transcript path.
277	// For existing sessions, resolves the agent from session state's AgentType.
278	// For new sessions, uses the --agent flag with auto-detection fallback.
279	func resolveAgentAndTranscript(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, existingState *session.State) (agent.Agent, string, error) {
280		ag, err := resolveAgent(existingState, agentName)
281		if err != nil {
282			return nil, "", err
283		}
284	
285		transcriptPath, err := resolveAndValidateTranscript(ctx, sessionID, ag)
286		if err != nil {
287			// Auto-detect: try all other agents.
288			detectedAg, detectedPath, detectErr := detectAgentByTranscript(ctx, sessionID, agentName)
289			if detectErr != nil {
290				return nil, "", fmt.Errorf("%w (also tried auto-detecting other agents: %w)", err, detectErr)
291			}
292			ag = detectedAg
293			transcriptPath = detectedPath
294			logging.Info(ctx, "auto-detected agent from transcript", "agent", ag.Name())
295			fmt.Fprintf(w, "Auto-detected agent: %s\n", ag.Name())
296		}
297	
298		return ag, transcriptPath, nil
299	}
300	
301	// resolveAgent resolves the agent to use. For existing sessions with an AgentType,
302	// uses agent.GetByAgentType. Otherwise falls back to the --agent flag.
303	func resolveAgent(existingState *session.State, agentName types.AgentName) (agent.Agent, error) {
304		if existingState != nil && existingState.AgentType != "" {
305			ag, err := agent.GetByAgentType(existingState.AgentType)
306			if err == nil {
307				return ag, nil
308			}
309			// Fall through to flag-based resolution.
310		}
311		ag, err := agent.Get(agentName)
312		if err != nil {
313			return nil, fmt.Errorf("agent %q not available: %w", agentName, err)
314		}
315		return ag, nil
316	}
317	
318	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
319	// project directories if needed.
320	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
321		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
322		if err != nil {
323			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
324		}
325		// Only call PrepareTranscript when the file already exists — it flushes
326		// in-progress writes, but can't conjure a file that was never started.
327		// This avoids agents like Cursor polling for 3s on non-existent files
328		// during auto-detection.
329		if _, statErr := os.Stat(transcriptPath); statErr == nil {
330			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
331				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
332					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
333				}
334			}
335			return transcriptPath, nil
336		}
337		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
338		if searchErr == nil {
339			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
340			return found, nil
341		}
342		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
343		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
344	}
