146	// ErrorResponse represents a standard API error response.
147	type ErrorResponse struct {
148		Error string `json:"error"`
149	}
150	
151	// CheckResponse returns an error if the response status code indicates failure.
152	// For non-2xx responses, it reads and parses the error message from the body.
153	// The caller is responsible for closing resp.Body.
154	func CheckResponse(resp *http.Response) error {
155		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
156			return nil
157		}
158	
159		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
160		if err != nil {
161			return fmt.Errorf("API error: status %d", resp.StatusCode)
162		}
163	
164		var apiErr ErrorResponse
165		if err := json.Unmarshal(body, &apiErr); err == nil && strings.TrimSpace(apiErr.Error) != "" {
166			return fmt.Errorf("API error: %s (status %d)", apiErr.Error, resp.StatusCode)
167		}
168	
169		text := strings.TrimSpace(string(body))
170		if text != "" {
171			return fmt.Errorf("API error: %s (status %d)", text, resp.StatusCode)
172		}
173	
174		return fmt.Errorf("API error: status %d", resp.StatusCode)
175	}
