117	// settingsTargetFile determines which settings file to write to based on flags
118	// and which files exist. Unlike determineSettingsTarget, this correctly handles
119	// local-only repos by checking for settings.local.json when settings.json is absent.
120	func settingsTargetFile(ctx context.Context, useLocal, useProject bool) (string, string) {
121		if useLocal {
122			return settings.EntireSettingsLocalFile, configDisplayLocal
123		}
124		if useProject {
125			return settings.EntireSettingsFile, configDisplayProject
126		}
127	
128		// No explicit flag — write to whichever file exists.
129		// Check project file first, then local.
130		projectAbs, err := paths.AbsPath(ctx, settings.EntireSettingsFile)
131		if err == nil {
132			if _, statErr := os.Stat(projectAbs); statErr == nil {
133				return settings.EntireSettingsFile, configDisplayProject
134			}
135		}
136		localAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
137		if err == nil {
138			if _, statErr := os.Stat(localAbs); statErr == nil {
139				return settings.EntireSettingsLocalFile, configDisplayLocal
140			}
141		}
142	
143		// Neither exists — default to project
144		return settings.EntireSettingsFile, configDisplayProject
145	}
