147	// parseCheckpointRemoteFlag parses a "provider:owner/repo" string into its components.
148	// Supported providers: "github".
149	func parseCheckpointRemoteFlag(value string) (provider, repo string, err error) {
150		parts := strings.SplitN(value, ":", 2)
151		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
152			return "", "", fmt.Errorf("expected format provider:owner/repo (e.g., github:org/checkpoints-repo), got %q", value)
153		}
154	
155		provider = parts[0]
156		repo = parts[1]
157	
158		switch provider {
159		case "github":
160			// valid
161		default:
162			return "", "", fmt.Errorf("unsupported provider %q (supported: github)", provider)
163		}
164	
165		repoParts := strings.SplitN(repo, "/", 2)
166		if len(repoParts) != 2 || repoParts[0] == "" || repoParts[1] == "" {
167			return "", "", fmt.Errorf("repo must be in owner/name format, got %q", repo)
168		}
169	
170		return provider, repo, nil
171	}
