236	// handleRotationConflict handles the case where remote /full/current was rotated.
237	// Merges local /full/current into the latest remote archived generation to avoid
238	// duplicating checkpoint data, then adopts remote's /full/current as local.
239	func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
240		// Use the latest remote-only archive
241		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
242		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
243	
244		// Fetch the latest archived generation
245		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
