396		// Push only the latest archived generation (most likely to be newly created)
397		repo, err := OpenRepository(ctx)
398		if err != nil {
399			return
400		}
401		store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
402		archived, err := store.ListArchivedGenerations()
403		if err != nil || len(archived) == 0 {
404			return
405		}
406		latest := archived[len(archived)-1]
407		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
408	}
